426	/**
427	  * @brief  BSP LCD Reset
428	  *         Hw reset the LCD DSI activating its XRES signal (active low for some time)
429	  *         and desactivating it later.
430	  *         This signal is only cabled on Discovery Rev B and beyond.
431	  */
432	void BSP_LCD_Reset(void)
433	{
434	#if !defined(USE_STM32469I_DISCO_REVA)
435	  /* Disco Rev B and beyond : reset the LCD by activation of XRES (active low) connected to PH7 */
436	  GPIO_InitTypeDef  gpio_init_structure;
437	
438	  __HAL_RCC_GPIOH_CLK_ENABLE();
439	
440	  /* Configure the GPIO on PH7 */
441	  gpio_init_structure.Pin   = GPIO_PIN_7;
442	  if(Lcd_Driver_Type == LCD_CTRL_NT35510)
443	  {
444	    /* Push Pull Mode is required for TechShine LCD (NT35510) */
445	    gpio_init_structure.Mode  = GPIO_MODE_OUTPUT_PP;
446	  }
447	  else
448	  {
449	    gpio_init_structure.Mode  = GPIO_MODE_OUTPUT_OD;
450	  }
451	  gpio_init_structure.Pull  = GPIO_NOPULL;
452	  gpio_init_structure.Speed = GPIO_SPEED_HIGH;
453	
454	  HAL_GPIO_Init(GPIOH, &gpio_init_structure);
455	
456	  /* Activate XRES active low */
457	  HAL_GPIO_WritePin(GPIOH, GPIO_PIN_7, GPIO_PIN_RESET);
458	
459	  HAL_Delay(20); /* wait 20 ms */
460	
461	  /* Deactivate XRES */
462	  HAL_GPIO_WritePin(GPIOH, GPIO_PIN_7, GPIO_PIN_SET);
463	
464	  /* Wait for 20ms after releasing XRES before sending commands */
465	  HAL_Delay(20);
466	#else
467	  /* Nothing to do in case of Disco Rev A */
468	#endif /* USE_STM32469I_DISCO_REVA == 0 */
469	}
