 71	static void DrawLogo(uint32_t x0, uint32_t y0)
 72	{
 73	  for (uint32_t y = 0; y < LOGO_PTIT_HEIGHT; y++)
 74	  {
 75	    for (uint32_t x = 0; x < LOGO_PTIT_WIDTH; x++)
 76	    {
 77	      uint32_t pixel = logo_ptit_data[y * LOGO_PTIT_WIDTH + x];
 78	      uint8_t a = (pixel >> 24) & 0xFF;
 79	      if (a > 0)
 80	      {
 81	        if (a == 255)
 82	        {
 83	          BSP_LCD_DrawPixel(x0 + x, y0 + y, pixel);
 84	        }
 85	        else
 86	        {
 87	          uint32_t r = (pixel >> 16) & 0xFF;
 88	          uint32_t g = (pixel >> 8) & 0xFF;
 89	          uint32_t b = pixel & 0xFF;
 90	          r = (r * a + 255 * (255 - a)) / 255;
 91	          g = (g * a + 255 * (255 - a)) / 255;
 92	          b = (b * a + 255 * (255 - a)) / 255;
 93	          BSP_LCD_DrawPixel(x0 + x, y0 + y, 0xFF000000UL | (r << 16) | (g << 8) | b);
 94	        }
 95	      }
 96	    }
 97	  }
 98	}
